class TestFinalAuditWiring:
    """T008: do_cmd wires final review results into evidence export."""

    def test_final_audit_reads_final_job_review(self, tmp_path):
        """_build_final_audit should include final_job_review data when present."""
        from dataclasses import dataclass, field

        from apps.cli.commands.do_cmd import _build_final_audit

        @dataclass
        class FakeTask:
            task_id: str = "T001"
            status: str = "applied_to_job_workspace"
            reviewer_verdict: str = "pass"
            test_passed: bool = True
            safe_diff_files: list = field(default_factory=list)

        @dataclass
        class FakeJob:
            tasks: list = field(default_factory=lambda: [FakeTask()])
            state: str = "completed"

        @dataclass
        class FakePromo:
            status: str = "dry_run"

        ev_dir = tmp_path / "evidence"
        ev_dir.mkdir()
        # Write final_job_review.json
        fjr = {"verdict": "PASS", "findings": [], "job_id": "test-job"}
        (ev_dir / "final_job_review.json").write_text(json.dumps(fjr))
        # Write token_cost_policy.json
        tcp = {"cost_risk_findings": [{"code": "ESTIMATE_MISSING"}]}
        (ev_dir / "token_cost_policy.json").write_text(json.dumps(tcp))

        result = _build_final_audit(FakeJob(), FakePromo(), str(ev_dir))
        assert result.get("final_job_review_verdict") == "PASS"
        assert result.get("final_job_review_ref") == "final_job_review.json"
        assert result.get("token_cost_policy_ref") == "token_cost_policy.json"
        assert result.get("token_cost_risk_findings_count") == 1

class TestPathSanitizerHardening:
    """R-4336: Path sanitizer must cover /mnt/, .data/job_workspaces/, etc."""

    def test_mnt_path_sanitized(self):
        from apps.cli.commands.do_cmd import _sanitize_shareable_paths
        data = {"ref": "/mnt/data/project/src/main.py"}
        result = _sanitize_shareable_paths(data)
        assert "/mnt/" not in result["ref"]

    def test_data_job_workspaces_sanitized(self):
        from apps.cli.commands.do_cmd import _sanitize_shareable_paths
        data = {"path": "/mnt/storage/.data/job_workspaces/abc123/workspace"}
        result = _sanitize_shareable_paths(data)
        assert ".data/job_workspaces" not in result["path"]
        assert "[workspace]" in result["path"]

    def test_data_root_sanitized(self):
        from apps.cli.commands.do_cmd import _sanitize_shareable_paths
        data = {"path": "/home/user/.data/runs"}
        result = _sanitize_shareable_paths(data)
        assert ".data/" not in result["path"]

    def test_evidence_dir_outside_tmp_sanitized(self):
        from apps.cli.commands.do_cmd import _sanitize_shareable_paths
        data = {"path": "/mnt/data/remedy-job-evidence-abc123/job_flow.json"}
        result = _sanitize_shareable_paths(data)
        assert "evidence/current/job_flow.json" == result["path"]

    def test_no_private_paths_in_shareable(self):
        from apps.cli.commands.do_cmd import _sanitize_shareable_paths
        paths = [
            "/tmp/remedy-job-evidence-abc/manifest.json",
            "/home/alice/project/file.py",
            "/Users/bob/code/file.py",
            "/private/var/folders/abc/file.py",
            "/mnt/data/project/file.py",
            "/mnt/storage/.data/job_workspaces/abc/workspace",
        ]
        for p in paths:
            result = _sanitize_shareable_paths({"ref": p})
            for prefix in ["/tmp/", "/home/", "/Users/", "/private/",
                           "/mnt/"]:
                assert prefix not in result["ref"], \
                    f"Path {p} leaked prefix {prefix}: {result['ref']}"
